CREATE TABLE public.organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.organizations TO authenticated; GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, user_id uuid NOT NULL, UNIQUE(organization_id,user_id));
GRANT SELECT ON public.memberships TO authenticated; GRANT ALL ON public.memberships TO service_role;
ALTER TABLE public.memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY memberships_own ON public.memberships FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_org_member(org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_org_member(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_org_member(uuid) TO authenticated;
CREATE POLICY organizations_member ON public.organizations FOR SELECT TO authenticated USING(public.is_org_member(id));
CREATE FUNCTION public.create_organization(org_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE new_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF char_length(trim(org_name)) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid organization name'; END IF; INSERT INTO public.organizations(name,created_by) VALUES(trim(org_name),auth.uid()) RETURNING id INTO new_id; INSERT INTO public.memberships(organization_id,user_id) VALUES(new_id,auth.uid()); RETURN new_id; END $$;
REVOKE ALL ON FUNCTION public.create_organization(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_organization(text) TO authenticated;
CREATE TABLE public.stations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), name text NOT NULL CHECK(char_length(name) BETWEEN 1 AND 100), food text NOT NULL CHECK(char_length(food) BETWEEN 1 AND 100), capacity_kg numeric NOT NULL CHECK(capacity_kg>0 AND capacity_kg<=10000), closing_time text NOT NULL DEFAULT '20:00' CHECK(closing_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.stations TO authenticated; GRANT ALL ON public.stations TO service_role;
ALTER TABLE public.stations ENABLE ROW LEVEL SECURITY;
CREATE POLICY stations_member ON public.stations FOR ALL TO authenticated USING(public.is_org_member(organization_id)) WITH CHECK(public.is_org_member(organization_id));
CREATE TABLE public.station_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), station_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('reading','refill')), weight_kg numeric NOT NULL CHECK(weight_kg>=0 AND weight_kg<=10000 AND (kind='reading' OR weight_kg>0)), recorded_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL DEFAULT auth.uid(), FOREIGN KEY(station_id,organization_id) REFERENCES public.stations(id,organization_id) ON DELETE CASCADE);
GRANT SELECT,INSERT ON public.station_events TO authenticated; GRANT ALL ON public.station_events TO service_role;
ALTER TABLE public.station_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.station_events FOR SELECT TO authenticated USING(public.is_org_member(organization_id));
CREATE POLICY events_insert ON public.station_events FOR INSERT TO authenticated WITH CHECK(public.is_org_member(organization_id) AND created_by=auth.uid());
CREATE TABLE public.manager_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), station_id uuid NOT NULL, decision text NOT NULL CHECK(char_length(decision) BETWEEN 1 AND 100), note text NOT NULL CHECK(char_length(note) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL DEFAULT auth.uid(), FOREIGN KEY(station_id,organization_id) REFERENCES public.stations(id,organization_id) ON DELETE CASCADE);
GRANT SELECT,INSERT ON public.manager_actions TO authenticated; GRANT ALL ON public.manager_actions TO service_role;
ALTER TABLE public.manager_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY actions_read ON public.manager_actions FOR SELECT TO authenticated USING(public.is_org_member(organization_id));
CREATE POLICY actions_insert ON public.manager_actions FOR INSERT TO authenticated WITH CHECK(public.is_org_member(organization_id) AND created_by=auth.uid());
CREATE INDEX memberships_user_idx ON public.memberships(user_id); CREATE INDEX stations_org_idx ON public.stations(organization_id); CREATE INDEX events_station_time_idx ON public.station_events(station_id,recorded_at); CREATE INDEX events_org_idx ON public.station_events(organization_id); CREATE INDEX actions_station_idx ON public.manager_actions(station_id); CREATE INDEX actions_org_idx ON public.manager_actions(organization_id);